# 7z on the formats besides 7z, run under 7-Zip 26.03 (the oracle: Scoop's 7z.exe on
# Windows) and under cash's builtin: gzip, bzip2, xz, zstd and lzma streams, and tars,
# kept here as hex (made by cash 1.8.0's gzip, bzip2 and xz from "hello stream\n" of
# 2026-10-07 08:00 UTC, and 3000 numbers in 4 KiB xz blocks; zstd's by cash 1.10's
# zstd, with and without its checksum; tars by cash 1.8.0's tar in GNU, ustar, pax and
# v7 formats, with a name too long for one header). 7z_formats.out is 7-Zip's output.
#
# As in 7z_cases.sh, `z` turns 7-Zip's CRLF and `\` into LF and `/`. 7-Zip shows times
# in Windows' own zone: the fixtures' 08:00 UTC is 10:00 in Brussels, and the pax
# tar's other times are two hours later than UTC there too.
#
# Regenerate the golden file (on Windows, with Scoop's 7-Zip and a cash without the
# builtin, such as 1.9.0), then shift the Brussels times to UTC:
#   cash 7z_formats.sh | awk '{ s = $0; o = "";
#     while (match(s, /2026-10-07 [0-9][0-9]:/)) {
#       o = o substr(s, 1, RSTART + 10) sprintf("%02d", substr(s, RSTART + 11, 2) - 2) ":";
#       s = substr(s, RSTART + RLENGTH) }
#     print o s }' > 7z_formats.out

exec 2>&1 </dev/null
export TZ=UTC0
dir=$(mktemp -d)
cd "$dir" || exit 1
z() { 7z "$@" > "$dir/o.txt" 2>&1; r=$?; tr -d '\r' < "$dir/o.txt" | sed 's#\\#/#g'; echo "rc=$r"; }
unhex() { printf "$(printf '%s' "$1" | sed 's/../\\x&/g')"; }
unhex 1f8b080800fcc56a0003612e74787400cb48cdc9c957282e294a4dcce5020097f486bb0d000000 > a.txt.gz
unhex 425a6839314159265359746f435a000002d1800010400022469c0020002201a6408069a68c211149476f78bb9229c28483a37a1ad0 > a.txt.bz2
unhex fd377a585a000004e6d6b44604c0110d2101160000000000000000008888cd6801000c68656c6c6f2073747265616d0a000000004432b405aac6da0200012d0d79931d7e1fb6f37d010000000004595a > a.txt.xz
unhex 5d00008000ffffffffffffffff00341949ee8de916728c0b9ccbb8e907ec59fffe8be800 > a.txt.lzma
unhex 1f8b0800000000000003cb48cdc9c957282e294a4dcce5020097f486bb0d000000 > n.gz
unhex  > big.txt.xz
unhex 28b52ffd84380d00000069000068656c6c6f2073747265616d0a7bcf528b > a.txt.zst
unhex 28b52ffd80380d00000069000068656c6c6f2073747265616d0a > nc.zst
unhex  > gnu.tar
unhex  > ustar.tar
unhex  > posix.tar
unhex  > v7.tar

echo "== list"
for f in a.txt.gz a.txt.bz2 a.txt.xz a.txt.lzma n.gz big.txt.xz a.txt.zst nc.zst; do
  z l $f
  z l -slt $f
done

echo "== test"
for f in a.txt.gz a.txt.bz2 a.txt.xz a.txt.lzma n.gz big.txt.xz a.txt.zst nc.zst; do
  z t $f
done
z t -bb1 a.txt.gz

echo "== extract"
z x a.txt.gz -oout
stat -c '%Y %n' out/a.txt
z x a.txt.bz2 -obz
z e -so a.txt.xz
z e -so a.txt.lzma
z e -so a.txt.zst
z x n.gz -oout
z x big.txt.xz -oout
find out bz | sort
cat out/a.txt out/n bz/a.txt
wc -c < out/big.txt

echo "== names"
cp a.txt.gz noext
z l noext
cp a.txt.gz x.tgz
z l -ba x.tgz
cp a.txt.bz2 y.TBZ
z l -ba y.TBZ
cp a.txt.lzma l.bin
z l l.bin
z l -tlzma l.bin
z l -tgzip l.bin
cp a.txt.gz gz.7z
z l gz.7z
z t gz.7z

echo "== damaged"
cp a.txt.gz tail.gz
printf 'tailjunk' >> tail.gz
z t tail.gz
head -c 20 a.txt.gz > cut.gz
z t cut.gz
z l cut.gz
cp a.txt.gz crc.gz
printf 'X' | dd of=crc.gz bs=1 seek=33 conv=notrunc 2>/dev/null
z t crc.gz
cp a.txt.bz2 tail.bz2
printf 'tailjunk' >> tail.bz2
z t tail.bz2
cp a.txt.xz tail.xz
printf 'tailjunk' >> tail.xz
z l tail.xz
z t tail.xz
cat a.txt.gz a.txt.gz > two.gz
z l two.gz
z t two.gz
cat a.txt.bz2 a.txt.bz2 > two.bz2
z t two.bz2
z e -so two.gz
printf 'junk' > j.gz
z l j.gz
z t j.gz

echo "== tar"
for f in gnu.tar ustar.tar posix.tar v7.tar; do
  z l $f
  z l -slt $f
done
z t gnu.tar
z t -bb1 posix.tar
z x gnu.tar -otar
find tar | sort
cat tar/d/a.txt
z e -so ustar.tar d/sub/b.txt
z l -ba v7.tar
cp gnu.tar t.bin
z l -ba t.bin
head -c 3000 gnu.tar > cut.tar
z l cut.tar
z t cut.tar
head -c 1100 gnu.tar > short.tar
z t short.tar
cp gnu.tar bad.tar
printf 'XX' | dd of=bad.tar bs=1 seek=1100 conv=notrunc 2>/dev/null
z l bad.tar
z t bad.tar
